fn rerun_ask(t: &Ticket, a: &Attempt) -> Option<(String, &'static [&'static str])> {
    let (what, options): (String, &'static [&'static str]) = match &a.state {
        AttemptState::Failed { reason } => {
            // A failure at the checks was offered `check` too, and one
            // at the rewrite `keep`. A ticket written before the attempt
            // kept that has only the earlier question about it to say
            // so.
            let earlier = t
                .decisions
                .iter()
                .rev()
                .find(|d| d.name == "rerun" && d.attempt == Some((a.stage.clone(), a.n)));
            let offered = |o: &str| earlier.is_some_and(|d| d.options.iter().any(|x| x == o));
            let options: &'static [&'static str] = if a.failed_at_checks || offered("check") {
                &["rerun", "check", "park"]
            } else if a.failed_at_rewrite || offered("keep") {
                &["rerun", "keep", "park"]
            } else {
                &["rerun", "park"]
            };
            (format!("failed: {reason}"), options)
        }
        // A restart flags the attempts whose checks may be run again
        // under its new copy.
        AttemptState::Cancelled { reason } if a.failed_at_checks => (
            format!("was cancelled: {reason}"),
            &["rerun", "check", "park"],
        ),
        AttemptState::Cancelled { reason } => {
            (format!("was cancelled: {reason}"), &["rerun", "park"])
        }
        AttemptState::Starting | AttemptState::Running | AttemptState::Complete => return None,
    };
    let question = format!(
        "{} ({}) attempt {} {what}. Run it again?{}{}",
        a.stage,
        a.context,
        a.n,
        rerun_carries(t, &a.stage, a.n),
        rewrite_choices(a, options)
    );
    Some((question, options))
}

pub fn ticket_paths(t: &Ticket, p: Option<&Pipeline>) -> PathsView {
    let plan_files = shown_lane_files(t, p, "plan")
        .into_iter()
        .map(|(lane, a, path)| LaneFile {
            lane: lane.map(str::to_owned),
            stage: a.stage.clone(),
            path: path.clone(),
            reviewing: a.kind == AttemptKind::Workflow && a.is_open(),
            round: review_round(a),
        })
        .collect();
    let notes_files = lane_files(t, p, "notes")
        .into_iter()
        .map(|(lane, stage, path)| LaneFile {
            lane: lane.map(str::to_owned),
            stage: stage.to_owned(),
            path: path.clone(),
            ..LaneFile::default()
        })
        .collect();
    let last_round = t
        .attempts
        .iter()
        .rev()
        .flat_map(|a| a.rounds.iter().rev())
        .find_map(|r| r.feedback.clone());
    let review = t
        .attempts
        .iter()
        .rev()
        .filter(|a| a.kind == AttemptKind::Workflow)
        .find(|a| !a.artifacts.is_empty());
    let shown = t.shown("plan");
    let reviewed = shown.filter(|(a, _)| a.kind == AttemptKind::Workflow);
    let plan_rounds = review.map_or_else(Vec::new, plan_rounds);
    let round_file = last_round.or_else(|| plan_rounds.last().map(|r| r.feedback.clone()));
    let pr = t.attempts.iter().rev().find_map(|a| a.pr.as_ref());
    PathsView {
        plan: shown.map(|(_, path)| path.clone()),
        plan_stage: shown.map(|(a, _)| a.stage.clone()),
        plan_reviewed: reviewed.is_some(),
        plan_reviewing: reviewed.is_some_and(|(a, _)| a.is_open()),
        plan_round: reviewed.and_then(|(a, _)| review_round(a)),
        round_file,
        review_summary: t
            .attempts
            .iter()
            .rev()
            .find_map(|a| a.artifacts.get("summary").cloned()),
        notes: t.input("notes").cloned(),
        pr_url: pr.map(|pr| pr.url.clone()),
        pr_head: pr.map(|pr| pr.head.clone()),
        plan_rounds,
        plan_files,
        notes_files,
    }
}

